package vn.vinhkhang.warehouse;
import java.math.BigDecimal;import java.time.Instant;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.boot.ApplicationArguments;import org.springframework.boot.ApplicationRunner;import org.springframework.dao.DataIntegrityViolationException;
@RestController @RequestMapping("/api") public class Api implements ApplicationRunner {
 private final org.springframework.context.ConfigurableApplicationContext context;private volatile boolean initialized;private final JdbcTemplate db;private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();private final Map<String,Session> sessions=new ConcurrentHashMap<>();
 record Session(long id,String name,String role,Instant expiry){} record Login(String username,String password){}
 public Api(JdbcTemplate db,org.springframework.context.ConfigurableApplicationContext context){this.db=db;this.context=context;}
 @Transactional public void run(ApplicationArguments args){Accounts.bootstrap(db);initialized=true;if("true".equals(System.getenv("VK_DESKTOP"))){new Thread(()->{try{while(System.in.read()!=-1){}context.close();}catch(java.io.IOException e){context.close();}},"desktop-lifecycle").start();}}
 Session user(String token,boolean write){Session s=sessions.get(token==null?"":token.replaceFirst("^Bearer ",""));if(s==null||s.expiry.isBefore(Instant.now()))throw new Problem(401,"Phiên đăng nhập hết hạn");var current=db.queryForList("SELECT display_name,role FROM app_users WHERE id=? AND active=TRUE",s.id);if(current.isEmpty())throw new Problem(401,"Tài khoản đã ngừng hoạt động");s=new Session(s.id,(String)current.getFirst().get("DISPLAY_NAME"),(String)current.getFirst().get("ROLE"),s.expiry);if(write&&s.role.equals("VIEWER"))throw new Problem(403,"Tài khoản chỉ có quyền xem");return s;}
 Session admin(String token){Session s=user(token,true);if(!s.role.equals("ADMIN"))throw new Problem(403,"Cần quyền quản trị");return s;}
 void invalidateSessions(long id){sessions.entrySet().removeIf(e->e.getValue().id()==id);}
 void audit(Session s,String action,String entity,long id){db.update("INSERT INTO audit_log(user_id,action,entity,entity_id) VALUES(?,?,?,?)",s.id,action,entity,id);}
 long insert(String sql,Object... values){org.springframework.jdbc.support.GeneratedKeyHolder k=new org.springframework.jdbc.support.GeneratedKeyHolder();db.update(c->{var p=c.prepareStatement(sql,new String[]{"ID"});for(int i=0;i<values.length;i++)p.setObject(i+1,values[i]);return p;},k);return k.getKey().longValue();}
 String str(Map<String,Object> m,String k){String s=Objects.toString(m.get(k),"").trim();if(s.isEmpty()||s.length()>500)throw new Problem(400,"Thiếu hoặc quá dài: "+k);return s;}
 long num(Map<String,Object> m,String k){try{return Long.parseLong(str(m,k));}catch(NumberFormatException e){throw new Problem(400,"Giá trị không hợp lệ: "+k);}}
 BigDecimal dec(Map<String,Object> m,String k){try{BigDecimal v=new BigDecimal(str(m,k));if(v.signum()<=0||v.scale()>3||v.precision()>15)throw new NumberFormatException();return v;}catch(NumberFormatException e){throw new Problem(400,"Số lượng phải lớn hơn 0, tối đa 3 chữ số thập phân");}}
 @SuppressWarnings("unchecked") List<Map<String,Object>> lines(Map<String,Object> m,String k){Object v=m.get(k);if(!(v instanceof List<?> l)||l.isEmpty()||l.size()>1000)throw new Problem(400,"Danh sách không được rỗng");try{return (List<Map<String,Object>>)v;}catch(Exception e){throw new Problem(400,"Danh sách không hợp lệ");}}
 @PostMapping("/login") public Map<String,Object> login(@RequestBody Login l){var rows=db.queryForList("SELECT * FROM app_users WHERE username=? AND active=TRUE",l.username);if(rows.isEmpty()||l.password==null||!encoder.matches(l.password,(String)rows.getFirst().get("PASSWORD_HASH")))throw new Problem(401,"Sai tên đăng nhập hoặc mật khẩu");var r=rows.getFirst();String token=UUID.randomUUID().toString()+UUID.randomUUID();Session s=new Session(((Number)r.get("ID")).longValue(),(String)r.get("DISPLAY_NAME"),(String)r.get("ROLE"),Instant.now().plusSeconds(28800));sessions.put(token,s);audit(s,"LOGIN","users",s.id);return Map.of("token",token,"name",s.name,"role",s.role,"id",s.id,"account_kind",r.get("ACCOUNT_KIND"));}
 @PostMapping("/logout") public void logout(@RequestHeader(value="Authorization",required=false) String t){sessions.remove(t.replaceFirst("^Bearer ",""));}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status",initialized?"UP":"STARTING","version","0.0.6","instanceId",System.getenv().getOrDefault("VK_INSTANCE_ID","standalone"));}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(@RequestHeader(value="Authorization",required=false) String t){user(t,false);return Map.of("parts",db.queryForObject("SELECT COUNT(*) FROM parts WHERE deleted=FALSE",Integer.class),"stock",db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM stock_balances",BigDecimal.class),"vehicles",db.queryForObject("SELECT COUNT(*) FROM vehicles WHERE status='AVAILABLE' AND deleted=FALSE",Integer.class),"orders",db.queryForObject("SELECT COUNT(*) FROM production_orders WHERE status='DRAFT' AND deleted=FALSE",Integer.class),"lowStock",db.queryForList("SELECT p.id,CASE WHEN p.color_parent_id IS NULL THEN p.code ELSE (SELECT g.code||' · '||m.code||' · '||p.color FROM parts g JOIN vehicle_models m ON m.id=p.color_model_id WHERE g.id=p.color_parent_id) END code,p.name,p.minimum,COALESCE(s.quantity,0) quantity,s.average_unit_cost FROM parts p LEFT JOIN stock_balances s ON s.part_id=p.id AND s.location_id=1 WHERE p.deleted=FALSE AND COALESCE(s.quantity,0)<=0 ORDER BY p.code"));}
 @GetMapping("/{entity}") public List<Map<String,Object>> list(@PathVariable String entity,@RequestHeader(value="Authorization",required=false) String t){user(t,false);String sql=switch(entity){case "parts"->"SELECT * FROM parts WHERE deleted=FALSE ORDER BY id DESC";case "suppliers"->"SELECT * FROM suppliers WHERE deleted=FALSE ORDER BY id DESC";case "models"->"SELECT * FROM vehicle_models WHERE deleted=FALSE ORDER BY id DESC";case "stock"->"SELECT p.id,CASE WHEN p.color_parent_id IS NULL THEN p.code ELSE (SELECT g.code||' · '||m.code||' · '||p.color FROM parts g JOIN vehicle_models m ON m.id=p.color_model_id WHERE g.id=p.color_parent_id) END code,p.name,p.unit,p.minimum,p.color_parent_id,p.color_model_id,p.color,COALESCE(s.quantity,0) quantity,s.average_unit_cost FROM parts p LEFT JOIN stock_balances s ON s.part_id=p.id AND s.location_id=1 WHERE p.deleted=FALSE ORDER BY p.code";case "documents"->"SELECT d.*,s.name supplier FROM stock_documents d LEFT JOIN suppliers s ON s.id=d.supplier_id WHERE d.deleted=FALSE ORDER BY d.id DESC";case "bom"->"SELECT b.id,m.name model,b.version,b.status,COUNT(l.part_id) components FROM bom_versions b JOIN vehicle_models m ON m.id=b.model_id LEFT JOIN bom_lines l ON l.bom_id=b.id WHERE b.deleted=FALSE GROUP BY b.id,m.name,b.version,b.status ORDER BY b.id DESC";case "production"->"SELECT p.*,(SELECT COUNT(*) FROM vehicles v WHERE v.order_id=p.id AND v.deleted=FALSE) received_quantity,p.quantity-(SELECT COUNT(*) FROM vehicles v WHERE v.order_id=p.id AND v.deleted=FALSE) remaining_quantity,(SELECT LISTAGG(DISTINCT m.name,' / ') WITHIN GROUP (ORDER BY m.name) FROM production_order_lines l JOIN bom_versions b ON b.id=l.bom_id JOIN vehicle_models m ON m.id=b.model_id WHERE l.order_id=p.id) model FROM production_orders p WHERE p.deleted=FALSE ORDER BY p.id";case "vehicles"->"SELECT v.*,m.name model FROM vehicles v JOIN vehicle_models m ON m.id=v.model_id WHERE v.deleted=FALSE ORDER BY v.id DESC";case "shipments"->"SELECT s.*,COUNT(l.vehicle_id) quantity FROM vehicle_shipments s LEFT JOIN vehicle_shipment_lines l ON l.shipment_id=s.id WHERE s.deleted=FALSE GROUP BY s.id ORDER BY s.id DESC";case "audit"->"SELECT a.id,a.user_id,a.action,a.entity,a.entity_id,a.details,a.user_note,a.archived,a.created_at,u.display_name actor FROM audit_log a JOIN app_users u ON u.id=a.user_id WHERE a.archived=FALSE ORDER BY a.id DESC LIMIT 500";case "movements"->"SELECT s.*,CASE WHEN p.color_parent_id IS NULL THEN p.code ELSE (SELECT g.code||' · '||m.code||' · '||p.color FROM parts g JOIN vehicle_models m ON m.id=p.color_model_id WHERE g.id=p.color_parent_id) END code,p.name FROM (SELECT id,part_id,location_id,quantity,document_id,production_id,created_at,unit_cost FROM stock_movements UNION ALL SELECT -id,part_id,location_id,quantity,NULL,NULL,created_at,unit_cost FROM retained_stock_effects) s JOIN parts p ON p.id=s.part_id ORDER BY s.created_at DESC,s.id DESC";case "users"->{admin(t);yield "SELECT id,username,display_name,role,active,account_kind FROM app_users WHERE active=TRUE ORDER BY id";}default->throw new Problem(404,"Không tìm thấy danh mục");};return Set.of("parts","stock").contains(entity)?PartColors.catalog(db,sql):db.queryForList(sql);}
 @GetMapping("/stock-bom-groups") public Object stockBomGroups(@RequestHeader(value="Authorization",required=false) String t){user(t,false);var result=new ArrayList<Map<String,Object>>();for(String code:List.of("S800","S650")){
  var models=db.queryForList("SELECT id,name FROM vehicle_models WHERE deleted=FALSE AND UPPER(code)=?",code);var group=new LinkedHashMap<String,Object>();group.put("CODE",code);group.put("PART_IDS",List.of());group.put("BOM_VERSION",null);
  if(!models.isEmpty()){long model=((Number)models.getFirst().get("ID")).longValue();group.put("MODEL_ID",model);var bom=db.queryForList("SELECT id,version FROM bom_versions WHERE model_id=? AND status='ACTIVE' AND deleted=FALSE ORDER BY version DESC,id DESC LIMIT 1",model);
   if(!bom.isEmpty()){group.put("BOM_VERSION",bom.getFirst().get("VERSION"));group.put("PART_IDS",db.queryForList("SELECT DISTINCT p.id FROM parts p WHERE p.deleted=FALSE AND (p.id IN (SELECT part_id FROM bom_lines WHERE bom_id=?) OR (p.color_model_id=? AND p.color_parent_id IN (SELECT part_id FROM bom_lines WHERE bom_id=?))) ORDER BY p.id",Long.class,bom.getFirst().get("ID"),model,bom.getFirst().get("ID")));}
  }result.add(group);
 }return result;}
 @PostMapping("/{entity}") @Transactional public Map<String,Long> create(@PathVariable String entity,@RequestHeader(value="Authorization",required=false) String t,@RequestBody Map<String,Object> m){Session s=user(t,true);long id=switch(entity){case "parts"->{BigDecimal min=new BigDecimal(Objects.toString(m.getOrDefault("minimum",0)));if(min.signum()<0)throw new Problem(400,"Tồn tối thiểu không được âm");long part=insert("INSERT INTO parts(code,name,unit,minimum) VALUES(?,?,?,?)",str(m,"code"),str(m,"name"),str(m,"unit"),min);PartColors.configure(this,db,part,m);yield part;}case "suppliers"->insert("INSERT INTO suppliers(code,name,phone,address) VALUES(?,?,?,?)",str(m,"code"),str(m,"name"),m.get("phone"),m.get("address"));case "models"->insert("INSERT INTO vehicle_models(code,name) VALUES(?,?)",str(m,"code"),str(m,"name"));case "users"->{admin(t);String role=str(m,"role");if(!Set.of("ADMIN","WAREHOUSE","VIEWER").contains(role))throw new Problem(400,"Vai trò không hợp lệ");String pw=str(m,"password");Accounts.validate(pw);yield insert("INSERT INTO app_users(username,password_hash,display_name,role,account_kind) VALUES(?,?,?,?,?)",str(m,"username"),encoder.encode(pw),str(m,"display_name"),role,AccountKinds.value(m));}default->throw new Problem(400,"Dùng nghiệp vụ tương ứng để tạo");};audit(s,"CREATE",entity,id);return Map.of("id",id);}
 @PostMapping("/documents/draft") @Transactional public Map<String,Long> document(@RequestHeader(value="Authorization",required=false) String t,@RequestBody Map<String,Object> m){Session s=user(t,true);m=MaterialPricing.prepare(this,db,s,m,null);String type=str(m,"type");if(type.equals("IN")&&m.get("supplier_id")!=null)active("suppliers",Long.parseLong(m.get("supplier_id").toString()));if(!Set.of("IN","OUT").contains(type))throw new Problem(400,"Loại phiếu không hợp lệ");long id=insert("INSERT INTO stock_documents(code,type,supplier_id,location_id,note,created_by) VALUES(?,?,?,1,?,?)",str(m,"code"),type,m.get("supplier_id"),m.get("note"),s.id);for(var l:lines(m,"lines")){active("parts",num(l,"part_id"));BigDecimal cost=Costing.cost(l,"unit_cost");if(cost!=null&&cost.signum()<0)throw new Problem(400,"Đơn giá không được âm");db.update("INSERT INTO stock_document_lines(document_id,part_id,quantity,unit_cost,color_model_id) VALUES(?,?,?,?,?)",id,num(l,"part_id"),dec(l,"quantity"),cost,l.get("color_model_id"));}SupplierReturns.persist(db,id,m);SalesFlow.header(db,"PART",id,m);SalesFlow.prices(this,db,id,m);audit(s,"DRAFT","documents",id);return Map.of("id",id);}
 void move(long part,BigDecimal quantity,Long document,Long production){Costing.move(this,db,part,quantity,document,production,null,false);}
 @PostMapping("/documents/{id}/post") @Transactional public void post(@RequestHeader(value="Authorization",required=false) String t,@PathVariable long id){Session s=user(t,true);var r=db.queryForList("SELECT * FROM stock_documents WHERE id=? AND deleted=FALSE FOR UPDATE",id);if(r.isEmpty())throw new Problem(404,"Không tìm thấy phiếu");var d=r.getFirst();if(!d.get("STATUS").equals("DRAFT"))throw new Problem(409,"Phiếu đã được ghi sổ");SupplierReturns.validate(this,db,d,id);PartColors.ensureResolved(db,id);for(var l:db.queryForList("SELECT * FROM stock_document_lines WHERE document_id=? ORDER BY part_id",id)){var q=(BigDecimal)l.get("QUANTITY");if(d.get("RETURN_SOURCE_ID")!=null)Costing.move(this,db,((Number)l.get("PART_ID")).longValue(),q.negate(),id,null,(BigDecimal)l.get("UNIT_COST"),true);else move(((Number)l.get("PART_ID")).longValue(),d.get("TYPE").equals("IN")?q:q.negate(),id,null);}db.update("UPDATE stock_documents SET status='POSTED',posted_at=CURRENT_TIMESTAMP WHERE id=?",id);SalesFlow.post(this,db,"PART",id,s);audit(s,"POST","documents",id);}
 @GetMapping("/documents/{id}/lines") public Object documentLines(@RequestHeader(value="Authorization",required=false) String t,@PathVariable long id){user(t,false);return db.queryForList("SELECT l.*,p.code,p.name FROM stock_document_lines l JOIN parts p ON p.id=l.part_id WHERE document_id=?",id);}
 @PostMapping("/bom/version") @Transactional public Map<String,Long> bom(@RequestHeader(value="Authorization",required=false) String t,@RequestBody Map<String,Object> m){Session s=admin(t);active("vehicle_models",num(m,"model_id"));long id=insert("INSERT INTO bom_versions(model_id,version) VALUES(?,?)",num(m,"model_id"),num(m,"version"));for(var l:lines(m,"lines")){active("parts",num(l,"part_id"));PartColors.bomPart(db,num(l,"part_id"));db.update("INSERT INTO bom_lines(bom_id,part_id,quantity) VALUES(?,?,?)",id,num(l,"part_id"),dec(l,"quantity"));}audit(s,"CREATE_VERSION","bom",id);return Map.of("id",id);}
 @GetMapping("/bom/{id}/lines") public Object bomLines(@RequestHeader(value="Authorization",required=false) String t,@PathVariable long id){user(t,false);return db.queryForList("SELECT l.*,p.code,p.name FROM bom_lines l JOIN parts p ON p.id=l.part_id WHERE bom_id=?",id);}
 @PostMapping("/production/draft") @Transactional public Map<String,Long> production(@RequestHeader(value="Authorization",required=false) String t,@RequestBody Map<String,Object> m){Session s=user(t,true);long id=ProductionLines.create(this,db,s,m);audit(s,"DRAFT","production",id);return Map.of("id",id);}
 @PostMapping("/production/{id}/complete") @Transactional public void complete(@RequestHeader(value="Authorization",required=false) String t,@PathVariable long id,@RequestBody Map<String,Object> m){Session s=user(t,true);var rs=db.queryForList("SELECT * FROM production_orders WHERE id=? AND deleted=FALSE FOR UPDATE",id);if(rs.isEmpty())throw new Problem(404,"Không tìm thấy lệnh");var row=rs.getFirst();ProductionProgress.receive(this,db,s,id,m);}
 @PostMapping("/shipments/post") @Transactional public Map<String,Long> ship(@RequestHeader(value="Authorization",required=false) String t,@RequestBody Map<String,Object> m){Session s=user(t,true);SalesShipments.validate(this,m);long id=insert("INSERT INTO vehicle_shipments(code,customer,created_by) VALUES(?,?,?)",str(m,"code"),str(m,"customer"),s.id);for(var v:lines(m,"vehicles")){long vehicle=num(v,"id");if(db.update("UPDATE vehicles SET status='SHIPPED' WHERE id=? AND status='AVAILABLE' AND deleted=FALSE AND vehicle_type=?",vehicle,VehicleTypes.type(m))!=1)throw new Problem(409,"Xe không có sẵn hoặc đã xuất");db.update("INSERT INTO vehicle_shipment_lines(shipment_id,vehicle_id) VALUES(?,?)",id,vehicle);}ShipmentChargers.persist(this,db,s,id,m);SalesShipments.persist(db,this,id,m);SalesFlow.header(db,"VEHICLE",id,m);SalesFlow.post(this,db,"VEHICLE",id,s);audit(s,"SHIP","shipments",id);return Map.of("id",id);}
 @GetMapping("/reports") public Object reports(@RequestHeader(value="Authorization",required=false) String t){user(t,false);return PartColors.catalog(db,"SELECT p.id,p.code,p.name,p.unit,p.minimum,p.deleted,COALESCE(SUM(CASE WHEN m.quantity>0 THEN m.quantity ELSE 0 END),0) received,COALESCE(SUM(CASE WHEN m.quantity<0 THEN -m.quantity ELSE 0 END),0) issued,COALESCE(SUM(m.quantity),0) balance FROM parts p LEFT JOIN (SELECT part_id,group_key,SUM(quantity) quantity FROM stock_history GROUP BY part_id,group_key) m ON m.part_id=p.id GROUP BY p.id,p.code,p.name,p.unit,p.minimum,p.deleted ORDER BY p.code");}
 @PostMapping("/backup") public Map<String,String> backup(@RequestHeader(value="Authorization",required=false) String t){Session s=admin(t);String dir=System.getenv().getOrDefault("VK_DATA_DIR","./data");String folder=dir.replace("\\","/")+"/backups";try{java.nio.file.Files.createDirectories(java.nio.file.Path.of(folder));}catch(java.io.IOException e){throw new Problem(500,"Không tạo được thư mục sao lưu");}String file=folder+"/backup-"+System.currentTimeMillis()+"-"+UUID.randomUUID()+".zip";db.execute("BACKUP TO '"+file.replace("'","''")+"'");audit(s,"BACKUP","database",0);return Map.of("file",file);}
 void active(String table,long id){if(!Set.of("parts","suppliers","vehicle_models","bom_versions").contains(table))throw new IllegalArgumentException();if(db.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE id=? AND deleted=FALSE",Integer.class,id)!=1)throw new Problem(409,"Danh mục không tồn tại hoặc đã xóa");}
 static class Problem extends RuntimeException{final int status;Problem(int s,String m){super(m);status=s;}}
 @ExceptionHandler(Problem.class) ResponseEntity<?> problem(Problem e){return ResponseEntity.status(e.status).body(Map.of("message",e.getMessage()));}
 @ExceptionHandler(DataIntegrityViolationException.class) ResponseEntity<?> conflict(Exception e){return ResponseEntity.status(409).body(Map.of("message","Mã hoặc số khung/số máy bị trùng, dữ liệu tham chiếu không tồn tại, hoặc giá trị vượt giới hạn."));}
 @ExceptionHandler({NumberFormatException.class,ClassCastException.class}) ResponseEntity<?> invalid(Exception e){return ResponseEntity.badRequest().body(Map.of("message","Dữ liệu không đúng định dạng"));}
}


